// _offtest.mjs —— 断网模拟：把 fetch 打死，看门禁还能不能用
// 用法：node _offtest.mjs <pluginId> <serverStateDir>
import fs from 'node:fs';
import path from 'node:path';
import { createGate } from './license-gate.mjs';

const pluginId = process.argv[2] || 'dsh-workbench';
const srcDir = process.argv[3] || '/home/lgsj/.dsh/.cache/.s';
const work = '/tmp/offtest-' + pluginId.replace(/[^\w.-]/g, '_');
fs.rmSync(work, { recursive: true, force: true });
fs.mkdirSync(work, { recursive: true });

// 拷该插件的状态文件（文件名 = sha1(pluginId)[:8]）
import crypto from 'node:crypto';
const sha1 = s => crypto.createHash('sha1').update(String(s), 'utf-8').digest('hex');
const stName = sha1(pluginId).slice(0, 8) + '.json';
for (const f of [stName, 'lease.json', 'dev.key', 'dev.pub', '.clock', '.hb']) {
  try { fs.copyFileSync(path.join(srcDir, f), path.join(work, f)); } catch {}
}
console.log('work dir:', work, 'state:', fs.existsSync(path.join(work, stName)));

// —— 模拟断网：任何网络请求立刻 ENETUNREACH ——
let netCalls = 0;
globalThis.fetch = async () => { netCalls++; throw Object.assign(new Error('connect ENETUNREACH'), { code: 'ENETUNREACH' }); };

const gate = createGate({ pluginId, dataDir: work, poolTarget: 5000, lowWater: 500, logger: (m, d) => console.log('  [log]', m, d || '') });

const t0 = Date.now();
const st = await gate.state();
console.log('\n== state (断网) ==');
console.log(JSON.stringify(st, null, 2));
console.log('elapsed(state):', Date.now() - t0, 'ms, netCalls:', netCalls);

const n0 = netCalls;
const r = await gate.allow();
console.log('\n== allow (硬门禁消耗一张) ==');
console.log(JSON.stringify(r));
const st2 = await gate.state();
console.log('pool after allow:', st2.pool, '| reason:', st2.reason, '| usable:', st2.usable);
console.log('netCalls during allow:', netCalls - n0);

// 连续消耗 200 次，看会不会中途被拒
let ok = 0, denied = null, deniedAt = -1;
for (let i = 0; i < 200; i++) {
  const x = await gate.allow();
  if (x.allowed) ok++; else { denied = x; deniedAt = i; break; }
}
const st3 = await gate.state();
console.log('\n== 连打 200 次 ==\n成功:', ok, '| 首次被拒于第', deniedAt, '次', denied ? JSON.stringify(denied) : '');
console.log('剩余 pool:', st3.pool, '| usable:', st3.usable, '| reason:', st3.reason, '| reason_kind:', st3.reason_kind);
fs.rmSync(work, { recursive: true, force: true });
process.exit(0);
